BEGIN;
create temp table assertion_count(n integer);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name)values('ee730000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Agency SQL fixture'),('ee730000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','Other agency SQL fixture');
create function pg_temp.board(p uuid default'ee730000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.read_agency_observation(p,'11111111-1111-1111-1111-111111111111','{}')$$;
create function pg_temp.facts(product text default'siteforge')returns jsonb language sql as $$select public.agency_observation_evidence('ee730000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222',product)$$;
create function pg_temp.command()returns jsonb language sql as $$select jsonb_build_object('operation','review','product','siteforge','sourceHash',pg_temp.facts()->>'sourceHash','decision','investigate','reason','Private human review note')$$;
create function pg_temp.decide(i uuid,b jsonb,p uuid default'ee730000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.decide_agency_observation(i,p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.event(i uuid,product text,phase text,evidence text default'server_confirmed',at timestamptz default statement_timestamp()-interval'1 minute',p uuid default'ee730000-0000-4000-8000-000000000001',org uuid default'22222222-2222-2222-2222-222222222222')returns void language plpgsql as $$begin
 insert into public.shared_action_episodes(id,org_id,property_id,actor_id,origin)values(i,org,p,'11111111-1111-1111-1111-111111111111','console');
 insert into public.shared_action_events(id,episode_id,org_id,property_id,actor_id,product,action,evidence,phase,request,result,created_at)values(i,i,org,p,'11111111-1111-1111-1111-111111111111',product,'fixture.action',evidence,phase,'{"private":"secret request"}','{"private":"secret result"}',at);
end$$;

create function pg_temp.planboard(extra jsonb default '{}',p uuid default 'ee730000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.read_agency_plan(p,'11111111-1111-1111-1111-111111111111','{"product":"siteforge"}'::jsonb||extra)$$;
create function pg_temp.planinput()returns jsonb language sql as $$select jsonb_build_object('operation','save','product','siteforge','previousId',pg_temp.planboard()->'current'->'id','sourceHash',pg_temp.facts()->>'sourceHash','status','draft','reason','Private draft reason','plan',jsonb_build_object('goal','Review held work with the client','successMeasure','A person records the verified outcome and remaining uncertainty','steps',jsonb_build_array(jsonb_build_object('action','inspect_work','detail','Private draft instructions'))))$$;
create function pg_temp.saveplan(i uuid,b jsonb,p uuid default 'ee730000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.save_agency_plan(i,p,'11111111-1111-1111-1111-111111111111',b)$$;
select pg_temp.check_it(pg_temp.planboard()->'current'='null'and pg_temp.planboard()->'evidence'->>'failedCount'='0','empty evidence does not invent activity');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),pg_temp.planinput()||'{"status":"reviewed"}')->>'state'='draft_required','first plan must be a draft');
insert into st values('input',pg_temp.planinput());
insert into st values('saved',pg_temp.saveplan('ee730000-0000-4000-8000-000000000010',(select v from st where k='input')));
select pg_temp.check_it(v->>'state'='saved'and v->'record'->>'revision'='1'and v->'record'->'evidence'->>'failedCount'='0','exact first draft and zero-evidence snapshot retained')from st where k='saved';
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000010',(select v from st where k='input'))->>'state'='replayed','lost draft reply recovers same record');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000010',(select v||'{"reason":"Changed request"}'from st where k='input'))->>'state'='request_conflict','same identity cannot change draft');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000010',(select v from st where k='input'),'ee730000-0000-4000-8000-000000000002')->>'state'='request_conflict','same identity cannot cross properties');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),(select v from st where k='input'))->>'state'='revision_changed','stale editor cannot overwrite a new revision');
select pg_temp.check_it((select count(*)=1 from public.shared_action_events where id='ee730000-0000-4000-8000-000000000010'),'draft and recording commit once');
select pg_temp.check_it((select request::text not like '%Private%'and result::text not like '%Private%'and not training_eligible and result->'executionAuthorized'='false'from public.shared_action_events where id='ee730000-0000-4000-8000-000000000010'),'plan and reason excluded from shared stream; no training or execution');
select pg_temp.check_it((select count(*)=0 from public.shared_jobs where property_id='ee730000-0000-4000-8000-000000000001'),'draft reserves no executable jobs');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),pg_temp.planinput()||'{"executeNow":true}')->>'state'='invalid','caller cannot add execution authority');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),jsonb_set(pg_temp.planinput(),'{plan,steps,0,action}','"send_email"'))->>'state'='invalid','execution verbs rejected');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),jsonb_set(pg_temp.planinput(),'{plan}','{}'))->>'state'='invalid','incomplete goal rejected');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),jsonb_set(pg_temp.planinput(),'{plan,steps}','[]'))->>'state'='invalid','empty steps rejected');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),pg_temp.planinput()||'{"reason":4}')->>'state'='invalid','reason must be actual text');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),pg_temp.planinput()||'{"previousId":"bad"}')->>'state'='invalid','malformed parent rejected safely');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),(pg_temp.planinput()-'previousId'))->>'state'='invalid','parent is explicit even on first draft');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),jsonb_set(pg_temp.planinput()||'{"status":"reviewed"}','{plan,goal}','"Changed goal"'))->>'state'='draft_required','changed proposal must be saved before review');
insert into st values('review_input',pg_temp.planinput()||'{"status":"reviewed","reason":"Reviewed the exact saved draft"}');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000011',(select v from st where k='review_input'))->'record'->>'status'='reviewed','exact saved plan can be reviewed');
select pg_temp.check_it((select count(*)=2 from public.agency_plan_revisions where property_id='ee730000-0000-4000-8000-000000000001'),'review preserves draft');
insert into st values('stale_evidence',pg_temp.planinput());
select pg_temp.event(gen_random_uuid(),'siteforge','failed');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),(select v from st where k='stale_evidence'))->>'state'='evidence_changed','changed evidence rejects the draft');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000011',(select v from st where k='review_input'))->>'state'='replayed','committed review stays recoverable after evidence changes');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000012',jsonb_set(pg_temp.planinput()||'{"reason":"Client corrected the desired outcome"}','{plan,goal}','"Corrected goal from the client"'))->'record'->>'revision'='3','correction saves a third immutable version');
select pg_temp.check_it((select plan->>'goal'='Review held work with the client'from public.agency_plan_revisions where id='ee730000-0000-4000-8000-000000000010'),'original goal unchanged');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000013',jsonb_set(pg_temp.planinput()||'{"status":"withdrawn"}','{plan}',pg_temp.planboard()->'current'->'plan'))->'record'->>'status'='withdrawn','withdrawal retains current plan content');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),jsonb_set(pg_temp.planinput()||'{"status":"reviewed"}','{plan}',pg_temp.planboard()->'current'->'plan'))->>'state'='draft_required','withdrawn plans need a new draft before review');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000014',jsonb_build_object('operation','cancel_unused','product','siteforge','inputHash',repeat('a',64)))->'record'->>'kind'='cancel_unused','unused plan request closed durably');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000014',pg_temp.planinput())->>'state'='decision_cancelled','late save fenced');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000010',jsonb_build_object('operation','cancel_unused','product','siteforge','inputHash',repeat('a',64)))->'record'->>'kind'='save','closing a committed request recovers it');
select pg_temp.check_it(pg_temp.planboard('{"kind":"decision","decisionId":"ee730000-0000-4000-8000-000000000010"}')->>'state'='ready','actor receipt readable');
select pg_temp.check_it(pg_temp.planboard('{"kind":"decision","decisionId":"ee730000-0000-4000-8000-000000000010"}','ee730000-0000-4000-8000-000000000002')->>'state'='not_found','other-property receipt hidden');
select pg_temp.check_it(pg_temp.planboard('{"product":"bi","kind":"decision","decisionId":"ee730000-0000-4000-8000-000000000010"}')->>'state'='not_found','other-product receipt hidden');
select pg_temp.check_it(pg_temp.planboard('{"kind":"history","before":"9223372036854775808"}')->>'state'='invalid','oversize history cursor rejected');
do $$begin for i in 1..21 loop perform pg_temp.saveplan(gen_random_uuid(),pg_temp.planinput());end loop;end$$;
insert into st values('history',pg_temp.planboard('{"kind":"history"}'));
select pg_temp.check_it(jsonb_array_length(v->'items')=20 and v->>'nextBefore'is not null,'history has bounded cursor pages')from st where k='history';
select pg_temp.check_it(jsonb_array_length(pg_temp.planboard(jsonb_build_object('kind','history','before',(select v->>'nextBefore'from st where k='history')))->'items')=6,'history pagination has no gaps');
create function pg_temp.fail_plan_event()returns trigger language plpgsql as $$begin if new.action like'agency.plan.%'then raise exception 'fixture recording failure';end if;return new;end$$;
create trigger agency_plan_fixture_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_plan_event();
do $$begin begin perform pg_temp.saveplan('ee730000-0000-4000-8000-000000000019',pg_temp.planinput());raise exception 'expected failure'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(not exists(select 1 from public.agency_plan_revisions where id='ee730000-0000-4000-8000-000000000019'),'recording failure rolls back draft');end;end$$;
drop trigger agency_plan_fixture_failure on public.shared_action_events;
do $$begin begin update public.agency_plan_revisions set reason='Overwritten'where id='ee730000-0000-4000-8000-000000000010';raise exception 'expected failure'using errcode='P0002';exception when sqlstate'55000'then perform pg_temp.check_it(true,'plan history immutable');end;end$$;
select pg_temp.check_it(not has_table_privilege('authenticated','public.agency_plan_revisions','SELECT')and not has_table_privilege('anon','public.agency_plan_revisions','INSERT'),'no browser table access');
select pg_temp.check_it(not has_function_privilege('authenticated','public.save_agency_plan(uuid,uuid,uuid,jsonb)','EXECUTE')and not has_function_privilege('anon','public.read_agency_plan(uuid,uuid,jsonb)','EXECUTE'),'no browser direct RPC');
update public.profiles set role='viewer'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.planboard()->'canManage'='false','viewer has read-only plan');
select pg_temp.check_it(pg_temp.saveplan(gen_random_uuid(),pg_temp.planinput())->>'state'='forbidden','viewer cannot save');
select pg_temp.check_it(pg_temp.saveplan('ee730000-0000-4000-8000-000000000010',(select v from st where k='input'))->>'state'='forbidden','role rechecked before replay');
insert into public.organizations(id,name)values('ee730000-0000-4000-8000-000000000090','Plan transferred org');
select set_config('p11.team_scope','22222222-2222-2222-2222-222222222222',true);
update public.profiles set org_id='ee730000-0000-4000-8000-000000000090',role='admin'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.planboard()->>'state'='forbidden','former member cannot read plan');
set local session_replication_role=replica;update public.properties set org_id='ee730000-0000-4000-8000-000000000090'where id='ee730000-0000-4000-8000-000000000001';set local session_replication_role=origin;
select pg_temp.check_it(pg_temp.planboard()->'current'='null'and jsonb_array_length(pg_temp.planboard()->'items')=0,'new property owner cannot inherit former tenant notes');
select 'Agency plan assertions: '||n from assertion_count;
ROLLBACK;
